        kind: "code",
        title: "Область видимости переменных",
        code: `# Глобальная переменная
global_var = 100

def my_function():
    # Локальная переменная
    local_var = 50
    print("Внутри функции:")
    print("local_var =", local_var)  # доступно
    print("global_var =", global_var)  # доступно (чтение)

my_function()
print("Вне функции:")
print("global_var =", global_var)  # доступно
# print("local_var =", local_var)  # Ошибка! local_var не доступна здесь

# Изменение глобальной переменной внутри функции
counter = 0

def increment():
    global counter  # указываем, что используем глобальную переменную
    counter += 1

increment()
increment()
print("counter =", counter)  # 2`,
