        kind: "code",
        title: "Декоратор с параметрами",
        code: `def repeat(times):
    """Декоратор для повторения вызова"""
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

@repeat(3)
def say_hello():
    print("Привет!")

say_hello()
# Привет!
# Привет!
# Привет!

@repeat(2)
def greet(name):
    print(f"Привет, {name}!")

greet("Алиса")
# Привет, Алиса!
# Привет, Алиса!`,
