        kind: "code",
        title: "Декоратор для кэширования",
        code: `def cache(func):
    """Декоратор для кэширования результатов"""
    memo = {}
    
    def wrapper(*args):
        if args not in memo:
            memo[args] = func(*args)
        return memo[args]
    
    return wrapper

@cache
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

# Без кэша: очень медленно
# С кэшем: мгновенно
print(fibonacci(50))  # 12586269025`,
